#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "3mm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto l_vec = noarr::vector<'l'>();
constexpr auto m_vec = noarr::vector<'m'>();

struct tuning {
	// A: i x k
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: k x j
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec);
	// C: j x m
	DEFINE_PROTO_STRUCT(c_layout, m_vec ^ j_vec);
	// D: m x l
	DEFINE_PROTO_STRUCT(d_layout, l_vec ^ m_vec);
	// E: i x j
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec);
	// F: j x l
	DEFINE_PROTO_STRUCT(f_layout, l_vec ^ j_vec);
	// G: i x l
	DEFINE_PROTO_STRUCT(g_layout, l_vec ^ i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto B, auto C, auto D) {
	// A: i x k
	// B: k x j
	// C: j x m
	// D: m x l
	using namespace noarr;

	auto ni = A | get_length<'i'>();
	auto nk = A | get_length<'k'>();
	auto nj = B | get_length<'j'>();
	auto nm = C | get_length<'m'>();
	auto nl = D | get_length<'l'>();

	// A[i][k] = ((i * k + 1) % ni) / (5 * ni)
	// Use for_each to traverse A in its natural (cache-friendly) order.
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % ni) / (5 * ni);
	});

	// B[k][j] = ((k * (j + 1) + 2) % nj) / (5 * nj)
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)((k * (j + 1) + 2) % nj) / (5 * nj);
	});

	// C[j][m] = (j * (m + 3) % nl) / (5 * nl)
	traverser(C).for_each([=](auto state) {
		auto [j, m] = get_indices<'j', 'm'>(state);
		C[state] = (num_t)((j * (m + 3) % nl)) / (5 * nl);
	});

	// D[m][l] = ((m * (l + 2) + 2) % nk) / (5 * nk)
	traverser(D).for_each([=](auto state) {
		auto [m, l] = get_indices<'m', 'l'>(state);
		D[state] = (num_t)(((m * (l + 2) + 2) % nk)) / (5 * nk);
	});
}

// computation kernel
//
// Optimized loop orders for better data locality:
//
//   E = A * B :  E[i,j] += A[i,k] * B[k,j]
//     - A is laid out with k as the inner dimension (row-major in k for each i)
//     - B is laid out with j as the inner dimension (row-major in j for each k)
//     - E is laid out with j as the inner dimension (row-major in j for each i)
//     => Use loop order i, k, j so that:
//          * A[i,k] is loaded once per (i,k)
//          * inner loop walks j, giving contiguous access to both B[k, j] and E[i, j]
//
//   F = C * D :  F[j,l] += C[j,m] * D[m,l]
//     - C: inner dimension m
//     - D: inner dimension l
//     - F: inner dimension l
//     => Use loop order j, m, l to walk l contiguously in the innermost loop.
//
//   G = E * F :  G[i,l] += E[i,j] * F[j,l]
//     - E: inner dimension j
//     - F: inner dimension l
//     - G: inner dimension l
//     => Use loop order i, j, l so that:
//          * E[i,j] is loaded once per (i,j)
//          * inner loop walks l contiguously in F[j, l] and G[i, l]
//
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

	#pragma scop

	// ---------------------------------------------
	// E := A * B  (loop order: i, k, j)
	// ---------------------------------------------

	// 1) Explicitly zero E so we can accumulate over k with no extra conditionals.
	traverser(E).for_each([&](auto s) {
		E[s] = (num_t)0.0;
	});

	// 2) Outer loops over i and k, shared across E, A, B.
	//    For each (i, k), we:
	//      - load A(i, k) once
	//      - walk j contiguously, updating E(i, j) and reading B(k, j)
	traverser(E, A, B).template for_dims<'i', 'k'>([&](auto trav_ik) {
		// A[i, k] is invariant across the inner j loop, so cache it in a scalar.
		const num_t a_ik = A[trav_ik];

		// Inner loop over j only (since i,k are fixed).
		// This walks j in memory order for both B and E.
		trav_ik.for_each([&](auto state_ikj) {
			E[state_ikj] += a_ik * B[state_ikj];
		});
	});

	// ---------------------------------------------
	// F := C * D  (loop order: j, m, l)
	// ---------------------------------------------

	// 1) Zero F so we can accumulate over m.
	traverser(F).for_each([&](auto s) {
		F[s] = (num_t)0.0;
	});

	// 2) Outer loops over j and m.
	//    For each (j, m), we:
	//      - load C(j, m) once
	//      - walk l contiguously, updating F(j, l) and reading D(m, l)
	traverser(F, C, D).template for_dims<'j', 'm'>([&](auto trav_jm) {
		const num_t c_jm = C[trav_jm];

		// Inner loop over l only (since j,m are fixed).
		trav_jm.for_each([&](auto state_jml) {
			F[state_jml] += c_jm * D[state_jml];
		});
	});

	// ---------------------------------------------
	// G := E * F  (loop order: i, j, l)
	// ---------------------------------------------

	// 1) Zero G so we can accumulate over j.
	traverser(G).for_each([&](auto s) {
		G[s] = (num_t)0.0;
	});

	// 2) Outer loops over i and j.
	//    For each (i, j), we:
	//      - load E(i, j) once
	//      - walk l contiguously, updating G(i, l) and reading F(j, l)
	traverser(G, E, F).template for_dims<'i', 'j'>([&](auto trav_ij) {
		const num_t e_ij = E[trav_ij];

		// Inner loop over l only (since i,j are fixed).
		trav_ij.for_each([&](auto state_ijl) {
			G[state_ijl] += e_ij * F[state_ijl];
		});
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl) ^
		noarr::set_length<'m'>(nm);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto D = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout ^ set_lengths);
	auto E = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ set_lengths);
	auto F = noarr::bag(noarr::scalar<num_t>() ^ tuning.f_layout ^ set_lengths);
	auto G = noarr::bag(noarr::scalar<num_t>() ^ tuning.g_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_3mm(E.get_ref(), A.get_ref(), B.get_ref(),
	           F.get_ref(), C.get_ref(), D.get_ref(), G.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, G.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

