#include "defines.hpp"

// include benchmark-specific definitions
#include "3mm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto l_vec = noarr::vector<'l'>();
constexpr auto m_vec = noarr::vector<'m'>();

struct tuning {
	// A: i x k  (row-major in k: scalar ^ k_vec ^ i_vec)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: k x j  (row-major in j: scalar ^ j_vec ^ k_vec)
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec);
	// C: j x m  (row-major in m: scalar ^ m_vec ^ j_vec)
	DEFINE_PROTO_STRUCT(c_layout, m_vec ^ j_vec);
	// D: m x l  (row-major in l: scalar ^ l_vec ^ m_vec)
	DEFINE_PROTO_STRUCT(d_layout, l_vec ^ m_vec);
	// E: i x j  (row-major in j: scalar ^ j_vec ^ i_vec)
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec);
	// F: j x l  (row-major in l: scalar ^ l_vec ^ j_vec)
	DEFINE_PROTO_STRUCT(f_layout, l_vec ^ j_vec);
	// G: i x l  (row-major in l: scalar ^ l_vec ^ i_vec)
	DEFINE_PROTO_STRUCT(g_layout, l_vec ^ i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto B, auto C, auto D) {
	// A: i x k
	// B: k x j
	// C: j x m
	// D: m x l
	using namespace noarr;

	auto ni = A | get_length<'i'>();
	auto nk = A | get_length<'k'>();
	auto nj = B | get_length<'j'>();
	auto nm = C | get_length<'m'>(); // kept for parity with original code
	auto nl = D | get_length<'l'>();

	// Precompute division denominators once (purely an efficiency change,
	// preserves original arithmetic exactly).
	const num_t den_A = num_t(5 * ni);
	const num_t den_B = num_t(5 * nj);
	const num_t den_C = num_t(5 * nl); // note: intentionally uses nl, same as original
	const num_t den_D = num_t(5 * nk); // note: intentionally uses nk, same as original

	// A[i][k] = ((i * k + 1) % ni) / (5 * ni)
	// Layout of A: dims {i (outer), k (inner)} so iterating i then k gives
	// contiguous writes along k.
	traverser(A).template for_dims<'i', 'k'>([&](auto trav) {
		auto state = trav.state();
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = num_t((i * k + 1) % ni) / den_A;
	});

	// B[k][j] = ((k * (j + 1) + 2) % nj) / (5 * nj)
	// Layout of B: dims {k (outer), j (inner)}.
	traverser(B).template for_dims<'k', 'j'>([&](auto trav) {
		auto state = trav.state();
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = num_t((k * (j + 1) + 2) % nj) / den_B;
	});

	// C[j][m] = (j * (m + 3) % nl) / (5 * nl)
	// Note: uses nl in the modulo and denominator, exactly as in original code.
	// Layout of C: dims {j (outer), m (inner)}.
	traverser(C).template for_dims<'j', 'm'>([&](auto trav) {
		auto state = trav.state();
		auto [j, m] = get_indices<'j', 'm'>(state);
		C[state] = num_t((j * (m + 3) % nl)) / den_C;
	});

	// D[m][l] = ((m * (l + 2) + 2) % nk) / (5 * nk)
	// Note: uses nk in the modulo and denominator, exactly as in original code.
	// Layout of D: dims {m (outer), l (inner)}.
	traverser(D).template for_dims<'m', 'l'>([&](auto trav) {
		auto state = trav.state();
		auto [m, l] = get_indices<'m', 'l'>(state);
		D[state] = num_t((m * (l + 2) + 2) % nk) / den_D;
	});
}

// computation kernel
// The kernel is rewritten to improve data locality by choosing
// loop orders that respect the row-major layouts of all matrices.
// All loop nests are still expressed using Noarr traversers.
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

	#pragma scop

	// ---------------------------------------------------------------------
	// 1) Explicit initialization of E, F, G
	//    (in the original code this was done inside the outer loops)
	// ---------------------------------------------------------------------
	traverser(E).for_each([&](auto s) {
		E[s] = num_t(0.0);
	});
	traverser(F).for_each([&](auto s) {
		F[s] = num_t(0.0);
	});
	traverser(G).for_each([&](auto s) {
		G[s] = num_t(0.0);
	});

	// ---------------------------------------------------------------------
	// 2) E := A * B
	//
	// Original polyhedral-like order (in terms of logical loops):
	//   for i
	//     for j
	//       E[i,j] = 0
	//       for k
	//         E[i,j] += A[i,k] * B[k,j];
	//
	// We keep the accumulation order over k identical for each (i,j),
	// but we change the loop nest to:
	//   for i               (outer)
	//     for k             (middle)
	//       a_ik = A[i,k]
	//       for j           (inner, contiguous in memory)
	//         E[i,j] += a_ik * B[k,j];
	//
	// This order:
	//   - keeps the order in k the same (bitwise-identical sums),
	//   - makes accesses to A, B and E all follow their inner (contiguous)
	//     dimensions in the innermost loop,
	//   - reuses A[i,k] across the inner j-loop.
	// ---------------------------------------------------------------------
	traverser(E, A, B).template for_dims<'i', 'k'>([&](auto trav_ik) {
		// trav_ik has 'i' and 'k' fixed; 'j' remains free.
		// Load A[i,k] once and reuse in the inner j-loop.
		const num_t a_ik = A[trav_ik];

		trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
			// trav_ikj has 'i', 'k', 'j' fixed.
			// For E: dims {i,j}, for B: dims {k,j}. The extra index is ignored
			// in each structure as appropriate.
			E[trav_ikj] += a_ik * B[trav_ikj];
		});
	});

	// ---------------------------------------------------------------------
	// 3) F := C * D
	//
	// Analogue of the above for matrices:
	//   F(j,l) = sum_m C(j,m) * D(m,l)
	//
	// Layouts:
	//   C: dims {j (outer), m (inner)}  -> contiguous in m
	//   D: dims {m (outer), l (inner)}  -> contiguous in l
	//   F: dims {j (outer), l (inner)}  -> contiguous in l
	//
	// Loop order chosen:
	//   for j               (outer)
	//     for m             (middle)
	//       c_jm = C[j,m]
	//       for l           (inner, contiguous)
	//         F[j,l] += c_jm * D[m,l];
	//
	// Again, the accumulation order over m is preserved for each (j,l),
	// giving the same floating-point summation order as the original code.
	// ---------------------------------------------------------------------
	traverser(F, C, D).template for_dims<'j', 'm'>([&](auto trav_jm) {
		// trav_jm has 'j' and 'm' fixed; 'l' remains free.
		const num_t c_jm = C[trav_jm];

		trav_jm.template for_dims<'l'>([&](auto trav_jml) {
			// trav_jml has 'j', 'm', 'l' fixed.
			F[trav_jml] += c_jm * D[trav_jml];
		});
	});

	// ---------------------------------------------------------------------
	// 4) G := E * F
	//
	// G(i,l) = sum_j E(i,j) * F(j,l)
	//
	// Layouts:
	//   E: dims {i (outer), j (inner)}  -> contiguous in j
	//   F: dims {j (outer), l (inner)}  -> contiguous in l
	//   G: dims {i (outer), l (inner)}  -> contiguous in l
	//
	// Original logical order:
	//   for i
	//     for l
	//       G[i,l] = 0
	//       for j
	//         G[i,l] += E[i,j] * F[j,l];
	//
	// New order:
	//   for i               (outer)
	//     for j             (middle)
	//       e_ij = E[i,j]
	//       for l           (inner, contiguous)
	//         G[i,l] += e_ij * F[j,l];
	//
	// For each fixed (i,l), contributions still arrive in ascending j,
	// so the summation order over j is preserved. The innermost loop
	// now writes G[i,*] contiguously and reads F[j,*] contiguously.
	// ---------------------------------------------------------------------
	traverser(G, E, F).template for_dims<'i', 'j'>([&](auto trav_ij) {
		// trav_ij has 'i' and 'j' fixed; 'l' remains free.
		const num_t e_ij = E[trav_ij];

		trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
			// trav_ijl has 'i', 'j', 'l' fixed.
			G[trav_ijl] += e_ij * F[trav_ijl];
		});
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl) ^
		noarr::set_length<'m'>(nm);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto D = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout ^ set_lengths);
	auto E = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ set_lengths);
	auto F = noarr::bag(noarr::scalar<num_t>() ^ tuning.f_layout ^ set_lengths);
	auto G = noarr::bag(noarr::scalar<num_t>() ^ tuning.g_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_3mm(E.get_ref(), A.get_ref(), B.get_ref(),
	           F.get_ref(), C.get_ref(), D.get_ref(), G.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, G.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
