// computation kernel
//
// We preserve the mathematical definition:
//   E = A * B,  F = C * D,  G = E * F
// but reorder the loop nests to improve data locality.
//
// For each multiplication we choose an order where:
//   - The innermost loop walks the inner (contiguous) dimension
//   - The reused operand for that loop is kept in a scalar register
//
// Concretely:
//   E[i,j] = sum_k A[i,k] * B[k,j]  -> loops: i, k, j
//     - A[i,k] is constant across j  (kept in a register)
//     - B[k,j] and E[i,j] are contiguous in j
//
//   F[j,l] = sum_m C[j,m] * D[m,l]  -> loops: j, m, l
//     - C[j,m] is constant across l
//     - D[m,l] and F[j,l] are contiguous in l
//
//   G[i,l] = sum_j E[i,j] * F[j,l]  -> loops: i, j, l
//     - E[i,j] is constant across l
//     - F[j,l] and G[i,l] are contiguous in l
//
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	using namespace noarr;

	#pragma scop

	// ---------------------------------------------------------------------
	// 1) Explicitly zero E, F, G
	//    This replaces the "E[ij] = 0" style initialization inside the
	//    original innermost loops and avoids repeated stores.
	// ---------------------------------------------------------------------
	traverser(E).for_each([&](auto state) {
		E[state] = (num_t)0.0;
	});

	traverser(F).for_each([&](auto state) {
		F[state] = (num_t)0.0;
	});

	traverser(G).for_each([&](auto state) {
		G[state] = (num_t)0.0;
	});

	// ---------------------------------------------------------------------
	// 2) E := A * B
	//
	//    Loop order: i (rows of A/E), k (reduction dim), j (cols of B/E)
	//    - A is laid out as [i x k] with k inner -> A[i,k] is cheap to load
	//    - B and E are [k x j] / [i x j] with j inner -> we traverse j
	//      in the innermost loop for contiguous access.
	// ---------------------------------------------------------------------
	traverser(E, A, B).template for_dims<'i', 'k'>([&](auto trav_ik) {
		// trav_ik has 'i' and 'k' fixed, 'j' still free.
		const num_t a_ik = A[trav_ik]; // reused across all j in this (i,k) slice

		trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
			// This triple nest is equivalent to:
			// for i
			//   for k
			//     for j
			//       E[i,j] += A[i,k] * B[k,j];
			E[trav_ikj] += a_ik * B[trav_ikj];
		});
	});

	// ---------------------------------------------------------------------
	// 3) F := C * D
	//
	//    Loop order: j (rows of C/F), m (reduction dim), l (cols of D/F)
	//    - C is [j x m] with m inner
	//    - D and F are [m x l] / [j x l] with l inner
	//    - We fix (j,m), keep C[j,m] in a register, and sweep l contiguous.
	// ---------------------------------------------------------------------
	traverser(F, C, D).template for_dims<'j', 'm'>([&](auto trav_jm) {
		// trav_jm has 'j' and 'm' fixed, 'l' still free.
		const num_t c_jm = C[trav_jm]; // reused across l

		trav_jm.template for_dims<'l'>([&](auto trav_jml) {
			// Equivalent to:
			// for j
			//   for m
			//     for l
			//       F[j,l] += C[j,m] * D[m,l];
			F[trav_jml] += c_jm * D[trav_jml];
		});
	});

	// ---------------------------------------------------------------------
	// 4) G := E * F
	//
	//    Loop order: i (rows of G/E), j (reduction dim), l (cols of G/F)
	//    - E is [i x j] with j inner
	//    - F and G are [j x l] / [i x l] with l inner
	//    - We fix (i,j), keep E[i,j] in a register, and sweep l contiguous,
	//      giving good locality for both F and G.
	// ---------------------------------------------------------------------
	traverser(G, E, F).template for_dims<'i', 'j'>([&](auto trav_ij) {
		// trav_ij has 'i' and 'j' fixed, 'l' still free.
		const num_t e_ij = E[trav_ij]; // reused across l

		trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
			// Equivalent to:
			// for i
			//   for j
			//     for l
			//       G[i,l] += E[i,j] * F[j,l];
			G[trav_ijl] += e_ij * F[trav_ijl];
		});
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl) ^
		noarr::set_length<'m'>(nm);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto D = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout ^ set_lengths);
	auto E = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ set_lengths);
	auto F = noarr::bag(noarr::scalar<num_t>() ^ tuning.f_layout ^ set_lengths);
	auto G = noarr::bag(noarr::scalar<num_t>() ^ tuning.g_layout ^ set_lengths);

