// computation kernel
// Optimized for better data locality and reuse:
//  - E = A * B   uses loop order (i, k, j)
//    -> reuses A(i,k) across all j for fixed (i,k) and streams over rows of B and E
//  - F = C * D   uses loop order (j, m, l)
//    -> reuses C(j,m) across all l and streams over rows of D and F
//  - G = E * F   uses loop order (i, j, l)
//    -> reuses E(i,j) across all l and streams over rows of F and G
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

