	// --------------------------------------------------------------------
	// E := A * B
	// --------------------------------------------------------------------
	// Loop order: i (outer) -> k -> j (inner)
	//   for each row i:
	//     1) zero entire row E(i, :)
	//     2) for each k:
	//          a_ik = A(i, k)          -- scalar
	//          E(i, :) += a_ik * B(k,:)
	traverser(E, A, B).template for_dims<'i'>([&](auto trav_i) {
		// 1) Zero row E(i, :)
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			E[trav_ij] = (num_t)0.0;
		});

		// 2) Accumulate contributions for this row over k
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// state_ik has indices (i, k) fixed, j is still free
			auto state_ik = trav_ik.state();
			num_t a_ik = A[state_ik]; // A(i, k), reused across all j in this k-iteration

