			trav_ik.for_each([&](auto state_ijk) {
				E[state_ijk] += a_ik * B[state_ijk]; // E(i,j) += A(i,k) * B(k,j)
			});
		});
	});

	// --------------------------------------------------------------------
	// F := C * D
	// --------------------------------------------------------------------
	// Loop order: j (outer) -> m -> l (inner)
	//   for each row j:
	//     1) zero entire row F(j, :)
	//     2) for each m:
	//          c_jm = C(j, m)
	//          F(j, :) += c_jm * D(m, :)
	traverser(F, C, D).template for_dims<'j'>([&](auto trav_j) {
		// 1) Zero row F(j, :)
		trav_j.template for_dims<'l'>([&](auto trav_jl) {
			F[trav_jl] = (num_t)0.0;
		});

		// 2) Accumulate contributions for this row over m
		trav_j.template for_dims<'m'>([&](auto trav_jm) {
			// state_jm has indices (j, m) fixed, l is still free
			auto state_jm = trav_jm.state();
			num_t c_jm = C[state_jm]; // C(j, m), reused across all l in this m-iteration

			// Inner-most loop over l: stream over contiguous l in F and D
			trav_jm.for_each([&](auto state_jml) {
