	// F := C * D
	// Original order: for j, l, m
	// New order:      for j, m, l
	//
	// Data layout:
	//   C: dims 'j', 'm'  (m contiguous)
	//   D: dims 'm', 'l'  (l contiguous)
	//   F: dims 'j', 'l'  (l contiguous)
	//
